begin;
set local search_path=public,extensions,private;
select no_plan();
grant usage on schema extensions to authenticated;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select('a2110000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','join211-'||i||'@example.invalid','',now(),'{}','{}',now(),now()from generate_series(1,4)i;
select set_config('request.jwt.claims','{"sub":"a2110000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select set_config('test.org211',public.create_or_request_organization('Entreprise de fixture211','Organisation211','211000000000001','CLIENT_OWNER','join211-create')->>'organization_id',true);
insert into public.organization_memberships(id,organization_id,user_id,status)values('a2110000-0000-4000-8000-000000000101',current_setting('test.org211')::uuid,'a2110000-0000-4000-8000-000000000002','ACTIVE');
insert into public.organization_member_roles(membership_id,role_code)values('a2110000-0000-4000-8000-000000000101','CLIENT_ADMIN');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a2110000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select set_config('test.join211',public.request_organization_join_v1('211000000000001','CLIENT_VIEWER','Je travaille dans cette entreprise de fixture','join211-request')::text,true);
select set_config('test.unknown211',public.request_organization_join_v1('211000000000999','CLIENT_VIEWER','Demande de rattachement de fixture inconnue','join211-unknown')::text,true);
select is(current_setting('test.join211')::jsonb->>'outcome','JOIN_REQUEST_RECORDED','known ICE gives only a neutral receipt');
select is(current_setting('test.unknown211')::jsonb->>'outcome','JOIN_REQUEST_RECORDED','unknown ICE gives the same neutral outcome');
select is((select array_agg(key order by key)from jsonb_object_keys(current_setting('test.join211')::jsonb)key),array['outcome','receipt_id']::text[],'response never discloses organization ID/name/owners');
select is(public.request_organization_join_v1('211000000000001','CLIENT_VIEWER','Je travaille dans cette entreprise de fixture','join211-request'),current_setting('test.join211')::jsonb,'request replay preserves receipt');
select is((public.get_organization_join_workspace_v1(null,1)->>'review_total')::integer,0,'requester cannot enumerate another organization owner inbox');
select is((public.get_organization_join_workspace_v1(null,1)->>'my_total')::integer,2,'requester sees their own receipts including a neutral unresolved one');
select throws_ok($$select public.request_organization_join_v1('211000000000001','CLIENT_OWNER','Demande de prise de contrôle de fixture','join211-owner-injection')$$,'22023','INVALID_JOIN_REQUEST','join cannot request a platform or owner privilege');
reset role;
select is((select count(*)::integer from public.notification_instances where organization_id=current_setting('test.org211')::uuid and event_type='OrganizationJoinRequestedV1'),1,'exactly the existing owner receives one durable notification');
select is((select count(*)::integer from public.notification_deliveries d join public.notification_instances n on n.id=d.notification_id where n.organization_id=current_setting('test.org211')::uuid and n.event_type='OrganizationJoinRequestedV1'and d.channel='EMAIL'),0,'workflow never claims an unconfigured email delivery');
select set_config('test.receipt211',current_setting('test.join211')::jsonb->>'receipt_id',true);
select set_config('test.hash211',(select request_hash from public.organization_join_requests where id=current_setting('test.receipt211')::uuid),true);
select set_config('test.access211',(select access_request_id::text from public.organization_join_requests where id=current_setting('test.receipt211')::uuid),true);
set local role authenticated;
select throws_ok($$select public.decide_organization_join_v1(current_setting('test.receipt211')::uuid,true,1,current_setting('test.hash211'),'Auto approbation de fixture','join211-self')$$,'42501','JOIN_DECISION_DENIED','requester cannot approve themselves');
select set_config('request.jwt.claims','{"sub":"a2110000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.decide_organization_join_v1(current_setting('test.receipt211')::uuid,true,1,current_setting('test.hash211'),'Décision manager de fixture','join211-manager')$$,'42501','JOIN_DECISION_DENIED','manager cannot substitute for the owner decision');
select set_config('request.jwt.claims','{"sub":"a2110000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.decide_organization_join_v1(current_setting('test.receipt211')::uuid,true,1,current_setting('test.hash211'),'Décision sans MFA de fixture','join211-aal1')$$,'42501','JOIN_DECISION_DENIED','owner requires AAL2');
select set_config('request.jwt.claims','{"sub":"a2110000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select is((public.get_organization_join_workspace_v1(current_setting('test.org211')::uuid,1)->>'review_total')::integer,1,'only owner can read the scoped real pending request');
select throws_ok($$select public.decide_organization_access_request(current_setting('test.access211')::uuid,true)$$,'42501','OWNER_JOIN_REVIEW_REQUIRED','legacy decision cannot bypass the CAS review');
select throws_ok($$select public.decide_organization_join_v1(current_setting('test.receipt211')::uuid,true,null,current_setting('test.hash211'),'Version absente de fixture','join211-null-version')$$,'40001','STALE_JOIN_REQUEST','null version is refused before membership mutation');
select throws_ok($$select public.decide_organization_join_v1(current_setting('test.receipt211')::uuid,true,1,repeat('f',64),'Empreinte erronée de fixture','join211-wrong-hash')$$,'40001','STALE_JOIN_REQUEST','review must match exact request hash');
select set_config('test.decision211',public.decide_organization_join_v1(current_setting('test.receipt211')::uuid,true,1,current_setting('test.hash211'),'Identité professionnelle confirmée pour cette fixture','join211-approve')::text,true);
select is(current_setting('test.decision211')::jsonb->>'outcome','JOIN_REQUEST_APPROVED','owner explicitly grants the requested read access');
select is(public.decide_organization_join_v1(current_setting('test.receipt211')::uuid,true,1,current_setting('test.hash211'),'Identité professionnelle confirmée pour cette fixture','join211-approve'),current_setting('test.decision211')::jsonb,'decision replays atomically');
reset role;
select is((select array_agg(r.role_code order by r.role_code)from public.organization_member_roles r join public.organization_memberships m on m.id=r.membership_id where m.organization_id=current_setting('test.org211')::uuid and m.user_id='a2110000-0000-4000-8000-000000000003'and r.revoked_at is null),array['CLIENT_VIEWER']::text[],'only requested read role is granted, no economic or owner rights');
select is((select count(*)::integer from public.audit_events where action='organization.join.decided'and resource_id=current_setting('test.receipt211')),1,'one owner decision audit exists despite replay');
select is((select count(*)::integer from private.organization_join_decision_permits),0,'transactional permits cannot be reused or retained');
select ok(not has_table_privilege('authenticated','public.organization_join_requests','SELECT')and not has_table_privilege('authenticated','private.organization_join_decision_permits','INSERT'),'request linkage and trusted decision permits are not exposed to callers');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a2110000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);
select set_config('test.legacy211',public.create_or_request_organization('Raison sociale ignorée','Nom ignoré','211000000000001','CLIENT_OWNER','join211-legacy-collision')::text,true);
select is(current_setting('test.legacy211')::jsonb->>'outcome','ACCESS_REQUESTED','legacy collision keeps a neutral compatible receipt');
reset role;
select is((select requested_role_code from public.organization_join_requests where id=(current_setting('test.legacy211')::jsonb->>'request_id')::uuid),'CLIENT_VIEWER','legacy collision can never implicitly request ownership');
select is((select count(*)::integer from public.organization_access_requests where requester_user_id='a2110000-0000-4000-8000-000000000004'and requested_role_code='CLIENT_OWNER'),0,'legacy collision leaves no hidden owner request');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a2110000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select set_config('test.provider_org211',public.create_or_request_organization('Passeport multi rôle211','Passeport211','211000000000002','PROVIDER_OWNER','join211-create-provider')->>'organization_id',true);
select set_config('request.jwt.claims','{"sub":"a2110000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select set_config('test.cross_domain211',public.request_organization_join_v1('211000000000002','CLIENT_VIEWER','Lecture Client explicitement demandée sur le même passeport','join211-client-on-provider')::text,true);
select set_config('request.jwt.claims','{"sub":"a2110000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select set_config('test.provider_workspace211',public.get_organization_join_workspace_v1(current_setting('test.provider_org211')::uuid,1)::text,true);
select is((current_setting('test.provider_workspace211')::jsonb->>'review_total')::integer,1,'Provider owner receives explicit Client read request on the same company passport');
select lives_ok($$select public.decide_organization_join_v1((current_setting('test.cross_domain211')::jsonb->>'receipt_id')::uuid,true,1,current_setting('test.provider_workspace211')::jsonb->'review_requests'->0->>'request_hash','Accès lecture Client consenti par le propriétaire Prestataire','join211-cross-domain-approve')$$,'same company owner can grant only the requested Client reading role');
reset role;
select is((select count(*)::integer from public.organization_member_roles r join public.organization_memberships m on m.id=r.membership_id where m.organization_id=current_setting('test.provider_org211')::uuid and m.user_id='a2110000-0000-4000-8000-000000000003'and r.role_code like'%OWNER'and r.revoked_at is null),0,'cross-domain read request never creates an Owner or economic permission');
select*from finish();rollback;
